        public static void Prepare(){AssetDatabase.Refresh();string path="Assets/HeartOfTheRain/Resources/HOTR_Wellworks/Design.asset";Directory.CreateDirectory(Path.GetDirectoryName(path));AssetDatabase.Refresh();var a=AssetDatabase.LoadAssetAtPath<WellworksDesignAssets>(path);if(!a){a=ScriptableObject.CreateInstance<WellworksDesignAssets>();AssetDatabase.CreateAsset(a,path);}Sprite S(string n)=>AssetDatabase.LoadAssetAtPath<Sprite>("Assets/HeartOfTheRain/App/WellworksDesign/Art/"+n+".png");a.shared=DailyGiftDesignAssets.Load();a.well=S("WW_Village_Well");a.badge=S("WW_Milestone_Badge");a.locked=S("WW_Lock");a.track=S("WW_Progress_Track");a.fill=S("WW_Progress_Fill");a.golden=S("Reward_Golden_Seeker");if(!a.shared||!a.well||!a.badge||!a.locked||!a.track||!a.fill||!a.golden)throw new Exception("Missing Wellworks binding");EditorUtility.SetDirty(a);AssetDatabase.SaveAssets();if(UIClarityGuard.Validate(out var log).Count!=0)throw new Exception(log.ToString());Directory.CreateDirectory(Output);File.WriteAllText(Path.Combine(Output,"Import.json"),"{\"status\":\"PASS_NATIVE_WELLWORKS_BINDINGS\"}");File.WriteAllText(Path.Combine(Output,"Import_Audit.txt"),log.ToString());}
        public static void Run(){SessionState.SetBool(Key,true);EditorSceneManager.OpenScene("Assets/HeartOfTheRain/App/FirstStart/Scenes/M65_First_Start.unity");UnityEngine.Object.FindFirstObjectByType<FirstStartPage>().reviewAlways=true;var group=Group();first=(int)group.GetType().GetMethod("GetTotalCount").Invoke(group,null);previous=(int)View().GetType().GetProperty("selectedSizeIndex",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).GetValue(View());SessionState.SetInt(Key+".first",first);SessionState.SetInt(Key+".previous",previous);var a=typeof(Editor).Assembly;foreach(var s in Sizes){var v=Activator.CreateInstance(a.GetType("UnityEditor.GameViewSize"),BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance,null,new object[]{Enum.Parse(a.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),s.x,s.y,"HOTR Wellworks R1"},null);group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{v});}EditorApplication.isPlaying=true;}
