        static WellworksView Fixture(int state){var p=PlayerProfile.New(new[]{5,5,3,2});p.completed=state==0?0:state==1?24:50;p.currentLevel=Math.Min(50,p.completed+1);if(state==1)new WellworksService(new ProfileService(new MemoryProfileRepository(p)),host.Wellworks.Schedule,true).Claim(10);if(state==1)ProfileService.ApplyGrant(p,WellworksService.Key(10),"wellworks",host.Wellworks.Schedule.milestones[0].grant);return new WellworksView{schedule=host.Wellworks.Schedule,player=p,enabled=true};}
