        static void Capture(string file){typeof(HomeLevelButtonReview).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{home,Path.Combine(Output,file)});report.frames.Add(file);}
        static void Rules(){Check(host.IsTransient,"Campaign isolated");page.Show();Check(Nodes["progress-clip"].gameObject.activeSelf==false,"Zero progress has no residual fill");page.Request("claim-10");Check(host.Service.Read().rewards.Count==0,"Unreached direct claim cannot grant");page.Hide();host.Service.Change(p=>{p.completed=50;p.currentLevel=50;return true;});host.Refresh();page.Show();var before=host.Service.Read();page.Request("claim-20");page.Request("claim-20");var after=host.Service.Read();Check(after.starting[0]==before.starting[0]+1&&after.starting[1]==before.starting[1]+1&&after.rewards.Count==1,"Separate Rocket/Bomb credited once on duplicate claim");Check(after.completed==50,"Claim cannot advance first-clear progress");Check(Nodes.ContainsKey("claim-0")&&Nodes.ContainsKey("claim-4"),"Earlier and later eligible rewards stay claimable");Check(!Field<RectTransform>(page,"panel").GetComponent<RectMask2D>(),"Ornament is unmasked");Check(!Field<RectTransform>(page,"panel").Find("Milestone effects"),"Reduced motion settles immediately");page.Hide();}
        static void LayoutChecks(){
            foreach(var t in Field<Canvas>(page,"canvas").GetComponentsInChildren<Text>()){
                Check(t.preferredHeight<=t.rectTransform.rect.height+1,"Text height "+t.name+" f="+t.fontSize+" preferred="+t.preferredHeight+" box="+t.rectTransform.rect.height);Check(t.text.All(c=>char.IsWhiteSpace(c)||t.font.HasCharacter(c)),"Glyph coverage "+t.name);
                if(t.name.StartsWith("claim-")&&t.name.EndsWith("-label")){Check(t.fontSize>=12&&t.preferredWidth<=t.rectTransform.rect.width+.1f,"Claim refits to available width "+t.name+" "+t.preferredWidth+"/"+t.rectTransform.rect.width);Check(t.rectTransform.rect.height>=44,"Claim touch height retained");}
            }
            var sc=Field<ScrollRect>(page,"scroll");var footer=Nodes["footer"].position;sc.verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();Check(Nodes["footer"].position==footer,"Footer fixed while body scrolls");sc.verticalNormalizedPosition=1;
            var corners=new Vector3[4];Nodes["close"].GetWorldCorners(corners);Check(corners.All(v=>Screen.safeArea.Contains(new Vector2(v.x,v.y))),"Close inside safe area");Check(Nodes["track"].GetComponent<Image>().pixelsPerUnitMultiplier==6&&Nodes["fill"].GetComponent<Image>().pixelsPerUnitMultiplier==8,"Corrected progress slice multipliers");Check(Nodes["well"].GetComponent<Image>().sprite.texture.mipmapCount>1,"Well art remains mipmapped");report.layouts++;
        }
        static void Tick(){try{if(EditorApplication.timeSinceStartup-began>280)throw new TimeoutException("Wellworks review timeout");if(!string.IsNullOrEmpty(report.error))throw new Exception(report.error);if(!EditorApplication.isPlaying||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.timeSinceStartup<next)return;
            if(!home){home=UnityEngine.Object.FindFirstObjectByType<HomePage>();if(!home||!home.GetComponent<PlayerProfileHost>()||!home.GetComponent<PlayerProfileHost>().Ready){home=null;return;}var firstPage=home.GetComponent<FirstStartPage>();if(!firstPage.Initialized){home=null;return;}if(firstPage.IsVisible){firstPage.Request("skip");firstPage.Request("skip");}home.State.reduceMotion=true;host=home.GetComponent<PlayerProfileHost>();page=home.GetComponent<WellworksPage>();Rules();Size(0);return;}
            if(index<75){int dim=index/15,lang=index%15/3,state=index%3;if(Screen.width!=Sizes[dim].x||Screen.height!=Sizes[dim].y)return;GameLocale.Select(lang);if(phase==0){page.Show();Render(Fixture(state));phase=1;next=EditorApplication.timeSinceStartup+.16;return;}LayoutChecks();Capture($"View_{GameLocale.Codes[lang]}_{state}_{Screen.width}x{Screen.height}.png");if(dim==1&&state==1){Field<ScrollRect>(page,"scroll").verticalNormalizedPosition=0;Canvas.ForceUpdateCanvases();Capture($"Scrolled_{GameLocale.Codes[lang]}_320x568.png");}page.Hide();phase=0;index++;if(index==75){Size(0);return;}if(index%15==0)Size(index/15);return;}
            if(Screen.width!=393||Screen.height!=852)return;GameLocale.Select(0);
