            if(index==78){var fx=Field<RectTransform>(page,"panel").Find("Milestone effects");Check(fx&&fx.GetComponentsInChildren<Image>().Length==10,"Confirmed ordinary claim spawns ten glints");Capture("Confirmed_Collection.png");page.Hide();Check(!fx.gameObject.activeSelf,"Close clears effects synchronously");home.State.reduceMotion=true;page.Show();page.Request("claim-30");page.Request("claim-40");page.Hide();home.State.reduceMotion=false;page.Show();page.Request("claim-50");index++;next=EditorApplication.timeSinceStartup+.15;return;}
